insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"classic-51","prompt":"What does a strong family depend on most?","theme":"Care, Family & Everyday Support","answers":["Care","Trust","Responsibility","Presence"],"sort_order":51,"version":"classic"},{"id":"classic-52","prompt":"What makes a caring relationship feel less transactional?","theme":"Care, Family & Everyday Support","answers":["Reciprocity","Affection","Patience","Reliability"],"sort_order":52,"version":"classic"},{"id":"classic-53","prompt":"What is hardest for money to replace in caring for someone?","theme":"Care, Family & Everyday Support","answers":["Attention","Trust","Time","Understanding"],"sort_order":53,"version":"classic"},{"id":"classic-54","prompt":"Why can asking for help feel difficult?","theme":"Care, Family & Everyday Support","answers":["Pride","Fear of burdening others","Lack of trust","Habit of doing everything alone"],"sort_order":54,"version":"classic"},{"id":"classic-55","prompt":"When can care turn into a power imbalance?","theme":"Care, Family & Everyday Support","answers":["One person decides everything","One person controls the money","One person has all the information","One person does all the work"],"sort_order":55,"version":"classic"},{"id":"classic-56","prompt":"How could society recognize care work better?","theme":"Care, Family & Everyday Support","answers":["Better pay","More time off","Stronger public services","More shared responsibility"],"sort_order":56,"version":"classic"},{"id":"classic-57","prompt":"What makes home feel restorative?","theme":"Care, Family & Everyday Support","answers":["Privacy","Safety","Calm","Cooperation"],"sort_order":57,"version":"classic"},{"id":"classic-58","prompt":"What does caring for others teach most strongly?","theme":"Care, Family & Everyday Support","answers":["Patience","Interdependence","Attention","Responsibility"],"sort_order":58,"version":"classic"},{"id":"classic-59","prompt":"Which kind of care is hardest to measure?","theme":"Care, Family & Everyday Support","answers":["Emotional care","Preventive care","Background planning","Companionship"],"sort_order":59,"version":"classic"},{"id":"classic-60","prompt":"When does community care feel most visible?","theme":"Care, Family & Everyday Support","answers":["During illness","During a crisis","During childcare","During everyday routines"],"sort_order":60,"version":"classic"},{"id":"classic-61","prompt":"What shapes a person''s identity most over time?","theme":"Identity, Roles & Social Expectations","answers":["Relationships","Work or school","Culture","Personal choices"],"sort_order":61,"version":"classic"},{"id":"classic-62","prompt":"When does a social role feel imposed rather than chosen?","theme":"Identity, Roles & Social Expectations","answers":["There is no real alternative","Refusal brings punishment","Judgment is constant","Dependence makes leaving hard"],"sort_order":62,"version":"classic"},{"id":"classic-63","prompt":"What most often changes how people see themselves?","theme":"Identity, Roles & Social Expectations","answers":["New relationships","New responsibilities","New ideas","New environments"],"sort_order":63,"version":"classic"},{"id":"classic-64","prompt":"When is a social label most useful?","theme":"Identity, Roles & Social Expectations","answers":["It builds solidarity","It explains an experience","It gives people language","It creates visibility"],"sort_order":64,"version":"classic"},{"id":"classic-65","prompt":"When does a label become limiting?","theme":"Identity, Roles & Social Expectations","answers":["It fixes expectations","It hides differences","It replaces curiosity","It becomes a stereotype"],"sort_order":65,"version":"classic"},{"id":"classic-66","prompt":"What helps people redefine who they are?","theme":"Identity, Roles & Social Expectations","answers":["Freedom","Community","Resources","Time"],"sort_order":66,"version":"classic"},{"id":"classic-67","prompt":"What creates the biggest gap between a person and the role expected of them?","theme":"Identity, Roles & Social Expectations","answers":["Expected behavior","Expected duties","Expected appearance","Expected attitude"],"sort_order":67,"version":"classic"},{"id":"classic-68","prompt":"Where do social norms feel strongest?","theme":"Identity, Roles & Social Expectations","answers":["Family","School","Workplace","Media"],"sort_order":68,"version":"classic"},{"id":"classic-69","prompt":"What makes a shared identity useful for collective action?","theme":"Identity, Roles & Social Expectations","answers":["A common need","A common harm","A common goal","Mutual support"],"sort_order":69,"version":"classic"},{"id":"classic-70","prompt":"What keeps identity from becoming fixed?","theme":"Identity, Roles & Social Expectations","answers":["Curiosity","Choice","Dialogue","Changing circumstances"],"sort_order":70,"version":"classic"},{"id":"classic-71","prompt":"What shapes behavior more strongly than people like to admit?","theme":"Identity, Roles & Social Expectations","answers":["Rewards","Punishments","Habits","The need to belong"],"sort_order":71,"version":"classic"},{"id":"classic-72","prompt":"What most often makes someone resist an assigned role?","theme":"Identity, Roles & Social Expectations","answers":["It feels unfair","It does not fit them","It feels restrictive","It reduces dignity"],"sort_order":72,"version":"classic"},{"id":"classic-73","prompt":"What is hardest about rejecting social expectations?","theme":"Identity, Roles & Social Expectations","answers":["Financial cost","Social conflict","Uncertainty","Loneliness"],"sort_order":73,"version":"classic"},{"id":"classic-74","prompt":"When does identity feel most authentic?","theme":"Identity, Roles & Social Expectations","answers":["When it is chosen","When it is supported","When it is lived consistently","When it can still change"],"sort_order":74,"version":"classic"},{"id":"classic-75","prompt":"How do people usually learn social norms?","theme":"Identity, Roles & Social Expectations","answers":["By observing others","By being corrected","By being rewarded","By repetition"],"sort_order":75,"version":"classic"},{"id":"classic-76","prompt":"What can a broad social category easily hide?","theme":"Identity, Roles & Social Expectations","answers":["Class differences","Cultural differences","Personal history","Power differences"],"sort_order":76,"version":"classic"},{"id":"classic-77","prompt":"What is most important for solidarity across differences?","theme":"Identity, Roles & Social Expectations","answers":["Listening","Shared goals","Mutual respect","Practical support"],"sort_order":77,"version":"classic"},{"id":"classic-78","prompt":"What changes the meaning of a social role from one generation to the next?","theme":"Identity, Roles & Social Expectations","answers":["Laws","Work patterns","Social movements","Technology"],"sort_order":78,"version":"classic"},{"id":"classic-79","prompt":"What is a powerful way to challenge a stereotype?","theme":"Identity, Roles & Social Expectations","answers":["Live differently","Speak openly","Organize together","Change institutions"],"sort_order":79,"version":"classic"},{"id":"classic-80","prompt":"What creates the biggest tension between individual identity and group identity?","theme":"Identity, Roles & Social Expectations","answers":["Uniqueness","Belonging","Representation","Responsibility"],"sort_order":80,"version":"classic"},{"id":"classic-81","prompt":"When does a new technology feel genuinely empowering?","theme":"Medicine, Technology & Body Change","answers":["The user controls it","The risks are clear","Access is fair","The benefit is meaningful"],"sort_order":81,"version":"classic"},{"id":"classic-82","prompt":"What makes medical advice feel trustworthy?","theme":"Medicine, Technology & Body Change","answers":["Options are explained","Consent is respected","Uncertainty is admitted","The person is listened to"],"sort_order":82,"version":"classic"},{"id":"classic-83","prompt":"What can influence a decision to change or modify the body?","theme":"Medicine, Technology & Body Change","answers":["Personal desire","Social pressure","A health need","Available technology"],"sort_order":83,"version":"classic"},{"id":"classic-84","prompt":"What is the biggest concern people may have about body-related technology?","theme":"Medicine, Technology & Body Change","answers":["Privacy","Inequality","Dependence","Unknown effects"],"sort_order":84,"version":"classic"},{"id":"classic-85","prompt":"Why might someone want a technology that enhances their abilities?","theme":"Medicine, Technology & Body Change","answers":["Convenience","Capability","Confidence","Opportunity"],"sort_order":85,"version":"classic"},{"id":"classic-86","prompt":"When can technology start to feel like control instead of freedom?","theme":"Medicine, Technology & Body Change","answers":["Use becomes mandatory","Tracking becomes constant","Access is unequal","There is no real opt-out"],"sort_order":86,"version":"classic"},{"id":"classic-87","prompt":"Why can a medical choice be less personal than it first appears?","theme":"Medicine, Technology & Body Change","answers":["Cost shapes it","Social norms shape it","Work expectations shape it","Expert authority shapes it"],"sort_order":87,"version":"classic"},{"id":"classic-88","prompt":"What should come before excitement about a new body-related technology?","theme":"Medicine, Technology & Body Change","answers":["Safety","Consent","Fair access","Public discussion"],"sort_order":88,"version":"classic"},{"id":"classic-89","prompt":"If technology removes a physical limit, what question should come first?","theme":"Medicine, Technology & Body Change","answers":["Who controls it?","Who benefits?","Who pays?","Who gets excluded?"],"sort_order":89,"version":"classic"},{"id":"classic-90","prompt":"What should health technology protect most strongly?","theme":"Medicine, Technology & Body Change","answers":["Autonomy","Privacy","Access","Informed consent"],"sort_order":90,"version":"classic"},{"id":"classic-91","prompt":"When can self-improvement start to feel like social pressure?","theme":"Medicine, Technology & Body Change","answers":["When comparison is constant","When jobs expect it","When trends demand it","When experts normalize it"],"sort_order":91,"version":"classic"},{"id":"classic-92","prompt":"What is a sign that wellness has become an obligation?","theme":"Medicine, Technology & Body Change","answers":["Feeling guilty for resting","Tracking everything","Feeling pressure to spend","Fear of falling behind"],"sort_order":92,"version":"classic"},{"id":"classic-93","prompt":"How could future human-enhancement technology widen inequality?","theme":"Medicine, Technology & Body Change","answers":["High cost","Unequal access","Unequal education","Unequal infrastructure"],"sort_order":93,"version":"classic"},{"id":"classic-94","prompt":"What human capacity should not be judged only by performance?","theme":"Medicine, Technology & Body Change","answers":["Speed","Output","Endurance","Efficiency"],"sort_order":94,"version":"classic"},{"id":"classic-95","prompt":"When does expert power feel excessive?","theme":"Medicine, Technology & Body Change","answers":["Alternatives are hidden","Questions are dismissed","Consent is rushed","Results are overpromised"],"sort_order":95,"version":"classic"},{"id":"classic-96","prompt":"When does dependence on technology become difficult to avoid?","theme":"Medicine, Technology & Body Change","answers":["Basic services require it","Social life requires it","Work requires it","Access systems require it"],"sort_order":96,"version":"classic"},{"id":"classic-97","prompt":"Who should have the strongest say over a person''s body data?","theme":"Medicine, Technology & Body Change","answers":["The person","Their care team","A public health system","A research community"],"sort_order":97,"version":"classic"},{"id":"classic-98","prompt":"If a device improves performance but reduces privacy, what might people value most?","theme":"Medicine, Technology & Body Change","answers":["Privacy","Convenience","Job security","Better performance"],"sort_order":98,"version":"classic"},{"id":"classic-99","prompt":"What is the best question to ask about ''upgrading'' the human body?","theme":"Medicine, Technology & Body Change","answers":["Necessary for whom?","Chosen by whom?","Paid for by whom?","Controlled by whom?"],"sort_order":99,"version":"classic"},{"id":"classic-100","prompt":"What describes a healthy relationship with innovation?","theme":"Medicine, Technology & Body Change","answers":["Curiosity","Caution","Democratic debate","Informed choice"],"sort_order":100,"version":"classic"}]'::jsonb) r;